        return { record }
      }
      default:
        return {}
    }
  }

  private predict(session: Session, open: OpenTurn, asOf: number): TurnEtaPrediction {
    const state = this.state(session)
    const core = etaCore({
      startTime: open.startTime,
      stepDurations: open.stepDurations,
